const storageKey = 'softinsa-sidebar-collapsed'

function SidebarItem({ item, collapsed, isOpen, onToggle }) {
  const Icon = item.icon

  if (item.subItems?.length) {
    return (
      <button
        type="button"
        onClick={onToggle}
        className={`softinsa-sidebar-item${collapsed ? ' is-collapsed' : ''}`}
        title={item.text.replace(/\n/g, ' ')}
      >
        <span className="softinsa-sidebar-item-icon-wrap">
          <Icon className="softinsa-sidebar-item-icon" aria-hidden="true" />
        </span>

        {!collapsed && (
          <>
            <span className="softinsa-sidebar-item-text">
              {item.text.split('\n').map((line) => (
                <span key={line}>{line}</span>
              ))}
            </span>

            <HiOutlineChevronRight
              className={`softinsa-sidebar-item-chevron${isOpen ? ' is-open' : ''}`}
              aria-hidden="true"
            />
          </>
        )}
      </button>
    )
  }

  return (
    <NavLink
      to={item.to}
      className={({ isActive }) =>
        `softinsa-sidebar-item${isActive ? ' active' : ''}${collapsed ? ' is-collapsed' : ''}`
      }
    >
      <span className="softinsa-sidebar-item-icon-wrap">
        <Icon className="softinsa-sidebar-item-icon" aria-hidden="true" />
      </span>

      {!collapsed && (
        <span className="softinsa-sidebar-item-text">
          {item.text}
        </span>
      )}
    </NavLink>
  )
}

function SidebarSubItems({ items }) {
  return (
    <ul className="softinsa-sidebar-subitems">
      {items.map((subItem) => (
        <li key={subItem.to}>
          <NavLink
            to={subItem.to}
            className={({ isActive }) =>
              `softinsa-sidebar-subitem${isActive ? ' active' : ''}`
            }
          >
            <span className="softinsa-sidebar-subitem-bullet" aria-hidden="true" />
            <span className="softinsa-sidebar-subitem-text">{subItem.text}</span>
          </NavLink>
        </li>
      ))}
    </ul>
  )
}

function ConsultorSidebar() {
  const [isCollapsed, setIsCollapsed] = useState(() => {
    if (typeof window === 'undefined') {
      return false
    }

    return window.localStorage.getItem(storageKey) === 'true'
  })
  const [openDropdowns, setOpenDropdowns] = useState({})
  const [navigationSections, setNavigationSections] = useState([])

  const toggleDropdown = (key) => {
    setOpenDropdowns((previous) => ({ ...previous, [key]: !previous[key] }))
  }

  const loadSidebar = async () => {
    try {
      const response = await getSideBarConsultor()

      const sections = [
        {
          title: 'Home',
          items: [
            {
              text: 'Dashboard',
              icon: IconDashboard,
              to: '/consultor/dashboard',
            },
          ],
        },
        {
          title: 'Área',
          items: [
            {
              text: response.nome_area,
              icon: IconArea,
              to: '/consultor/area',
              hasDropdown: true,
              subItems: (response.badges || []).map((badge) => ({
                text: badge.nome_badge,
                to: `/consultor/badge/${badge.nome_badge
                  .toLowerCase()
                  .replace(/\s+/g, '-')}`,
              })),
            },
          ],
        },
        {
          title: 'Home',
          items: [
            {
              text: 'Pedidos',
              icon: IconPedidos,
              to: '/consultor/pedidos',
            },
            {
              text: 'Objetivos',
              icon: IconObjetivos,
              to: '/consultor/objetivos',
            },
          ],
        },
      ]

      setNavigationSections(sections)
    } catch (error) {
      console.error('Erro ao carregar sidebar', error)
    }
  }

  useEffect(() => {
    loadSidebar()
  }, [])

  return (
    <aside className={`softinsa-sidebar-shell${isCollapsed ? ' is-collapsed' : ''}`}>
      <button
        type="button"
        className="softinsa-sidebar-toggle"
        onClick={() => setIsCollapsed((previousValue) => !previousValue)}
        aria-label={isCollapsed ? 'Abrir sidebar' : 'Fechar sidebar'}
        aria-expanded={!isCollapsed}
      >
        <svg
          xmlns="http://www.w3.org/2000/svg"
          width="18"
          height="18"
          viewBox="0 0 18 18"
          fill="none"
          className="softinsa-sidebar-toggle-arrow"
          aria-hidden="true"
        >
          <path d="M3.18752 9.20553L14.4375 9.20553" stroke="white" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" />
          <path d="M7.72496 13.724L3.18746 9.20595L7.72496 4.6872" stroke="white" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" />
        </svg>
      </button>

      <div className="softinsa-sidebar-panel">
        <div className="softinsa-sidebar-header">
          {!isCollapsed ? (
            <div className="softinsa-sidebar-logo-pill">
              <SoftinsaLogo />
            </div>
          ) : null}
        </div>

        <div className="softinsa-sidebar-top-line" />

        <div className="softinsa-sidebar-sections">
          {navigationSections.map((section) => (
            <section key={section.title} className="softinsa-sidebar-section" aria-label={section.title}>
              {!isCollapsed ? <div className="softinsa-sidebar-title">{section.title}</div> : null}

              <div className="softinsa-sidebar-items">
                {section.items.map((item) => {
                  const isOpen = Boolean(openDropdowns[item.to])
                  const showSubItems = item.subItems && item.subItems.length > 0 && isOpen

                  return (
                    <div key={item.to} className="softinsa-sidebar-item-group">
                      <SidebarItem
                        item={item}
                        collapsed={isCollapsed}
                        isOpen={isOpen}
                        onToggle={() => toggleDropdown(item.to)}
                      />
                      {showSubItems ? <SidebarSubItems items={item.subItems} /> : null}
                    </div>
                  )
                })}
              </div>

              {!isCollapsed ? <div className="softinsa-sidebar-divider" /> : null}
            </section>
          ))}
        </div>
      </div>
    </aside>
  )
}

export default memo(ConsultorSidebar)